// E2E — open tender bids go through the comparative statement like any quote.
//
//   node scripts/e2e_tender_cs.mjs
//
// The real walk, no stage forced by hand:
//   tender posted -> vendor1 and vendor2 bid from the supplier portal ->
//   deadline -> tender auto-closed -> Ready for CS (QUOTES_RECEIVED) ->
//   CS generated by the cs role -> submit -> HOD Procurement sends to requester ->
//   award + Capex/Opex class -> HOD confirms -> advance -> IN_FINANCE_REVIEW
//   (migration 075 retired cost approval; the CS exit goes to finance review)
//
// NOTE: on a database built by deploy/migrate.sh in bootstrap mode, 067 can be
// re-applied AFTER 075 and put back the old proc.fn_check_pr_transition(), and
// then the advance below fails with "Invalid PR status transition:
// QUOTES_RECEIVED -> IN_FINANCE_REVIEW". That is a database build-order issue,
// not a tender issue (e2e_cs_review.mjs fails the same way).
//
// What it pins for tenders specifically:
//   - every bid becomes a scored CS line, and the cheapest bid ranks 1,
//   - a vendor that joined but never bid is not on the CS,
//   - procurement sees both bidders on the CS (bidder-to-bidder sealing does not
//     hide them from the buyer),
//   - the award writes the winning bid back onto the request line,
//   - the PR leaves sourcing exactly as an invited RFQ would.
//
// Setup: vendor1/vendor2@example.com are mapped to IT_HARDWARE in the LOCAL
// database for the run and the mapping is restored on exit.

import { spawnSync } from 'node:child_process';

const API = process.env.API_BASE || 'http://127.0.0.1:33001';
const CONTAINER = process.env.PG_CONTAINER || 'procurement-portal-db';
const LAPTOP = '55555555-5555-5555-5555-555555555503';

let pass = 0, fail = 0;
const check = (c, l, d = '') => { if (c) { pass++; console.log(`  PASS  ${l}`); } else { fail++; console.log(`  FAIL  ${l}\n        ${typeof d === 'string' ? d : JSON.stringify(d)}`); } };

function sql(q) {
  const r = spawnSync('docker', ['exec', CONTAINER, 'psql', '-U', 'proc', '-d', 'procurementDB',
    '-X', '-A', '-F', '\t', '-t', '-c', q], { encoding: 'utf8' });
  if (r.status !== 0) throw new Error(r.stderr || `psql failed (${r.status})`);
  return r.stdout.split('\n').map(l => l.trim()).filter(Boolean).map(l => l.split('\t'));
}
async function api(path, { method = 'GET', token, body } = {}) {
  const r = await fetch(`${API}${path}`, {
    method,
    headers: { 'content-type': 'application/json', ...(token ? { authorization: `Bearer ${token}` } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const t = await r.text();
  let data = null; try { data = t ? JSON.parse(t) : null; } catch { data = { raw: t }; }
  return { status: r.status, data };
}
const login = async (email) =>
  (await api('/auth/login', { method: 'POST', body: { email, password: 'demo' } })).data?.token;
const ok2xx = (r) => r.status === 200 || r.status === 201;
const stageOf = (id) => sql(`SELECT status FROM proc.purchase_requisitions WHERE id='${id}'`)[0][0];

// ── setup: demo vendors in IT_HARDWARE, restored on exit ─────────────────────
const VENDORS = `('vendor1@example.com','vendor2@example.com','vendor3@example.com')`;
const before = sql(
  `SELECT vc.vendor_id, vc.is_active FROM core.vendor_categories vc
     JOIN core.users u ON u.vendor_id = vc.vendor_id
     JOIN core.categories c ON c.id = vc.category_id
    WHERE u.email IN ${VENDORS} AND c.code = 'IT_HARDWARE'`);
process.on('exit', () => {
  sql(`DELETE FROM core.vendor_categories vc USING core.users u, core.categories c
        WHERE u.vendor_id = vc.vendor_id AND c.id = vc.category_id
          AND u.email IN ${VENDORS} AND c.code = 'IT_HARDWARE'
          ${before.length ? `AND vc.vendor_id NOT IN (${before.map(b => `'${b[0]}'`).join(',')})` : ''}`);
  for (const [vid, active] of before) {
    sql(`UPDATE core.vendor_categories vc SET is_active = ${active === 't'} FROM core.categories c
          WHERE c.id = vc.category_id AND c.code = 'IT_HARDWARE' AND vc.vendor_id = '${vid}'`);
  }
  console.log('  (demo vendor category mapping restored)');
});
sql(`INSERT INTO core.vendor_categories (vendor_id, category_id, is_active)
     SELECT u.vendor_id, c.id, true FROM core.users u, core.categories c
      WHERE u.email IN ${VENDORS} AND c.code = 'IT_HARDWARE'
     ON CONFLICT (vendor_id, category_id) DO UPDATE SET is_active = true`);

const requester = await login('requester@pakboxes.pk');
const hod = await login('hod.sales@pakboxes.pk');
const hodProcurement = await login('hod.procurement@pakboxes.pk');
const procurement = await login('procurement@pakboxes.pk');
const cs = await login('cs@pakboxes.pk');
const vendor1 = await login('vendor1@example.com');
const vendor2 = await login('vendor2@example.com');
const vendors = sql(`SELECT u.email, v.id, v.legal_name FROM core.users u JOIN core.vendors v ON v.id = u.vendor_id
                      WHERE u.email IN ${VENDORS} ORDER BY u.email`);
const V = Object.fromEntries(vendors.map(([e, id, name]) => [e, { id, name }]));

// ── 1. a PR at procurement review, and its tender ────────────────────────────
console.log('\n== 1. tender posted ==');
const cc = (await api('/lookups/cost-centers', { token: requester })).data?.[0]?.id;
const created = await api('/pr', { method: 'POST', token: requester, body: {
  scope: 'Tender to CS e2e', expenseType: 'OPEX', costCenterId: cc, requiredByDate: '2026-12-31',
  title: 'Tender to CS e2e',
  // One line, so HOD approval does not split the request: auto-split children
  // carry no proc.pr_departments row (a pre-existing gap), and the CS blind
  // review refuses a request with no department approver. Same shape as the
  // fixture in e2e_cs_review.mjs.
  lines: [{ itemId: LAPTOP, quantity: 1, uom: 'EA', unitPriceEst: 30000 }] } });
const prId = created.data.id;
await api(`/pr/${prId}/advance`, { method: 'POST', token: hod,
  body: { lineDecisions: { 0: 'approved' }, reason: 'e2e' } });
if (stageOf(prId) !== 'IN_PROCUREMENT_REVIEW') {
  check(false, 'fixture PR at procurement review', stageOf(prId)); process.exit(1);
}
const posted = await api(`/pr/${prId}/tender`, { method: 'POST', token: procurement,
  body: { deadlineAt: new Date(Date.now() + 2 * 86400e3).toISOString(), notes: 'e2e to CS' } });
const rfqId = posted.data?.rfq?.id;
check(Boolean(rfqId), 'tender posted', posted.data?.rfq?.rfq_number ?? JSON.stringify(posted.data));

// ── 2. two vendors bid from the supplier portal; a third joins and never bids ─
console.log('\n== 2. bids ==');
async function bid(token, unitPrice, lead, warranty) {
  const j = await api(`/supplier/tenders/${rfqId}/join`, { method: 'POST', token });
  const inv = j.data?.invitationId;
  const form = await api(`/supplier/rfq/${inv}`, { token });
  const line = form.data.lines[0];
  return api(`/supplier/rfq/${inv}/quote`, { method: 'POST', token, body: {
    lines: [{ lineNo: line.lineNo, unitPrice }], totalAmount: unitPrice * line.qty,
    leadTime: lead, warranty, paymentTerms: '30 days' } });
}
check(ok2xx(await bid(vendor1, 29000, '14 days', '1 yr')), 'vendor1 bid 29,000');
check(ok2xx(await bid(vendor2, 27500, '7 days', '3 yr')), 'vendor2 bid 27,500 (cheapest, fastest, longest warranty)');
const vendor3 = await login('vendor3@example.com');
if (vendor3) {
  const j3 = await api(`/supplier/tenders/${rfqId}/join`, { method: 'POST', token: vendor3 });
  check(ok2xx(j3), 'vendor3 joined without bidding');
}

// ── 3. deadline -> closed -> Ready for CS ────────────────────────────────────
console.log('\n== 3. deadline and hand-off ==');
const early = await api(`/pr/${prId}/ready-for-cs`, { method: 'POST', token: procurement, body: { remarks: 'too early' } });
check(early.status === 400, 'Ready for CS refused while bidding is open', `${early.status}`);
sql(`UPDATE proc.rfq SET created_at=now()-interval '4 days', issued_at=now()-interval '4 days',
            initial_deadline_at=now()-interval '1 minute', deadline_at=now()-interval '1 minute'
      WHERE id='${rfqId}'`);
await api('/rfq/tenders/close-due', { method: 'POST', token: procurement });
check(sql(`SELECT state FROM proc.rfq WHERE id='${rfqId}'`)[0][0] === 'Closed', 'tender closed');
const ready = await api(`/pr/${prId}/ready-for-cs`, { method: 'POST', token: procurement, body: { remarks: 'tender closed' } });
check(ok2xx(ready), 'Ready for CS accepted', JSON.stringify(ready.data).slice(0, 200));
check(stageOf(prId) === 'QUOTES_RECEIVED', 'PR parked at QUOTES_RECEIVED', stageOf(prId));

// ── 4. CS generated from the bids ────────────────────────────────────────────
console.log('\n== 4. comparative statement ==');
const gen = await api(`/pr/${prId}/cs`, { method: 'POST', token: cs });
const csId = gen.data?.cs?.id ?? gen.data?.id;
check(ok2xx(gen) && Boolean(csId), 'CS generated by the cs role', `${gen.status} ${gen.data?.message ?? ''}`);
const csLines = gen.data?.lines ?? [];
const scored = new Set(csLines.map(l => l.vendor_id));
check(csLines.length === 2, 'one scored CS line per bid (2)', csLines.length);
check(scored.has(V['vendor1@example.com'].id) && scored.has(V['vendor2@example.com'].id), 'both bidders are on the CS');
if (vendor3) check(!scored.has(V['vendor3@example.com'].id), 'the vendor that joined but never bid is not on the CS');
const top = csLines.find(l => l.rank === 1);
check(top?.vendor_id === V['vendor2@example.com'].id, 'the cheapest, best bid ranks 1', top);

const screen = await api(`/pr/${prId}/cs`, { token: procurement });
const screenTxt = JSON.stringify(screen.data);
check(screen.status === 200 && screenTxt.includes(V['vendor1@example.com'].name) && screenTxt.includes(V['vendor2@example.com'].name),
  'procurement sees both bidders by name on the CS screen');

// ── 5. review chain, award, classification, confirm ──────────────────────────
console.log('\n== 5. review, award, confirm ==');
check(ok2xx(await api(`/cs/${csId}/review/submit`, { method: 'POST', token: cs })), 'CS submitted for review');
const sent = await api(`/cs/${csId}/review/send-to-requester`, { method: 'POST', token: hodProcurement });
check(ok2xx(sent), 'HOD Procurement sends it to the requester side', `${sent.status} ${sent.data?.message ?? ''}`);
const rfqLineNo = Number(sql(`SELECT min(line_no) FROM proc.rfq_lines WHERE rfq_id='${rfqId}'`)[0][0]);
const award = await api(`/cs/${csId}/award`, { method: 'POST', token: procurement,
  body: { lineNo: rfqLineNo, vendorId: V['vendor2@example.com'].id, qty: 1, justification: 'Lowest evaluated tender bid' } });
check(ok2xx(award), 'line awarded to the winning bidder', `${award.status} ${award.data?.message ?? ''}`);
const cls = await api(`/pr/${prId}/lines/classification`, { method: 'PATCH', token: procurement,
  body: { lines: [{ lineNo: 1, classification: 'OPEX_CONSUMABLE' }] } });
check(ok2xx(cls), 'line classified', `${cls.status} ${cls.data?.message ?? ''}`);
const myStatus = async (token) =>
  (await api('/supplier/tenders', { token })).data?.myBids?.find(b => b.rfqId === rfqId)?.status;
check(await myStatus(vendor2) === 'Tender closed',
  'before the CS is confirmed the winner is NOT told (award can still change)', await myStatus(vendor2));
const conf = await api(`/cs/${csId}/review/confirm`, { method: 'POST', token: hod });
check(ok2xx(conf), 'HOD confirms the statement', `${conf.status} ${conf.data?.message ?? ''}`);

const aw = sql(`SELECT vendor_id, awarded_qty FROM proc.cs_line_awards WHERE cs_id='${csId}' AND superseded_at IS NULL`);
check(aw.length === 1 && aw[0][0] === V['vendor2@example.com'].id && Number(aw[0][1]) === 1,
  'cs_line_awards: vendor2, qty 1', aw);
const prl = sql(`SELECT coalesce(preferred_vendor_id::text,'-') || '|' || unit_price_est FROM proc.pr_lines WHERE pr_id='${prId}' AND line_no=1`)[0][0].split('|');
check(Number(prl[1]) === 27500, 'request line carries the winning bid rate (27,500)', prl);
check(await myStatus(vendor2) === 'Won', 'My Bids: vendor2 sees Won once confirmed', await myStatus(vendor2));
check(await myStatus(vendor1) === 'Not selected', 'My Bids: vendor1 sees Not selected', await myStatus(vendor1));

// ── 6. out of sourcing, like any RFQ ─────────────────────────────────────────
console.log('\n== 6. on to finance review ==');
const adv = await api(`/pr/${prId}/advance`, { method: 'POST', token: procurement,
  body: { reason: 'CS confirmed on tender', csReviewConfirmed: true } });
check(ok2xx(adv) && adv.data?.matchedStep === 'cs_review_quotes', 'advance takes the CS exit', `${adv.status} ${adv.data?.matchedStep} ${adv.data?.message ?? ''}`);
check(stageOf(prId) === 'IN_FINANCE_REVIEW', 'PR reached IN_FINANCE_REVIEW, like any invited RFQ', stageOf(prId));

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
